 *
 * This source code is licensed under the Apache-2.0 license found in the
 * LICENSE file in the root directory of this source tree.
 */

import { usePrefix } from "../../internal/usePrefix.js";
import Form from "../Form/Form.js";
import { FormContext } from "./FormContext.js";
import "react";
import cx from "classnames";
import PropTypes from "prop-types";
import { jsx } from "react/jsx-runtime";
//#region src/components/FluidForm/FluidForm.tsx
/**
* Copyright IBM Corp. 2016, 2025
*
* This source code is licensed under the Apache-2.0 license found in the
* LICENSE file in the root directory of this source tree.
*/
const FluidForm = ({ className, children, ...other }) => {
	const prefix = usePrefix();
	const classNames = cx(`${prefix}--form--fluid`, className);
	return /* @__PURE__ */ jsx(FormContext.Provider, {
		value: { isFluid: true },
		children: /* @__PURE__ */ jsx(Form, {
			className: classNames,
			...other,
			children
		})
	});
};
FluidForm.propTypes = {
	/**
	* Provide children to be rendered inside of the <form> element
	*/
	children: PropTypes.node,
	/**
	* Provide a custom className to be applied on the containing <form> node
	*/
	className: PropTypes.string
};
//#endregion
export { FluidForm as default };
